CREATE OR REPLACE FUNCTION public.kinto_credit_points_v310(p_customer_id text, p_store_id text, p_currency text, p_whole_points bigint, p_fraction numeric, p_source_order_id text DEFAULT NULL::text)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
c text;
unit bigint;
days integer;
cur bigint;
n bigint:=0;
begin
if coalesce(p_customer_id,'')='' or coalesce(p_store_id,'')='' then
raise exception 'customer/store required';
end if;

if not exists(
select 1
from public.local_stores s
where s.id::text=p_store_id
) then
raise exception 'store not found';
end if;

if coalesce(p_whole_points,0)<0 then
raise exception 'negative points not allowed';
end if;

c:=public.kinto_normalize_currency_v310(p_currency);

select coupon_unit,coupon_days
into unit,days
from public.kinto_loyalty_settings
where id=1;

insert into public.kinto_loyalty_wallets(
customer_id,store_id,currency
)
values(
p_customer_id,p_store_id,c
)
on conflict do nothing;

update public.kinto_loyalty_wallets
set
progress_points=progress_points+coalesce(p_whole_points,0),
fractional_carry=greatest(
0,
least(coalesce(p_fraction,0),.99999999)
),
updated_at=now()
where customer_id=p_customer_id
and store_id=p_store_id
and currency=c
returning progress_points into cur;

-- Coupon tiers are currently defined only for IQD.
-- Other currencies keep accumulating their independent balance.
if c='IQD' then
while cur>=unit loop
insert into public.kinto_loyalty_coupons(
customer_id,
store_id,
currency,
points,
source_order_id,
expires_at,
funded_by
)
values(
p_customer_id,
p_store_id,
c,
unit,
p_source_order_id,
now()+make_interval(days=>days),
'vendor'
);

cur:=cur-unit;
n:=n+1;
end loop;
end if;

update public.kinto_loyalty_wallets
set
progress_points=cur,
updated_at=now()
where customer_id=p_customer_id
and store_id=p_store_id
and currency=c;

return n;
end $function$

CREATE OR REPLACE FUNCTION public.kinto_loyalty_order_v310()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
c text;
sid text;
r numeric;
x numeric;
whole bigint;
carry numeric;
enabled boolean;
fund text;
vendor_points numeric:=0;
kinto_points numeric:=0;
begin

sid:=public.kinto_order_store_id_v310(new);
c:=public.kinto_normalize_currency_v310(new.currency);

if new.status='تم التسليم'
and coalesce(old.status,'')<>'تم التسليم'
and sid is not null
and coalesce(new.total_price,0)>0
and not exists(
select 1
from public.kinto_loyalty_ledger
where order_id=new.id::text
and store_id=sid
and event_type='earn'
)
then
begin

insert into public.kinto_store_loyalty_settings(store_id)
values(sid)
on conflict do nothing;

select s.enabled,s.earn_rate
into enabled,r
from public.kinto_store_loyalty_settings s
where s.store_id=sid;

if enabled
and coalesce(r,0)>0
and new.customer_id is not null
then

insert into public.kinto_loyalty_wallets(
customer_id,
store_id,
currency
)
values(
new.customer_id::text,
sid,
c
)
on conflict do nothing;

select fractional_carry
into carry
from public.kinto_loyalty_wallets
where customer_id=new.customer_id::text
and store_id=sid
and currency=c
for update;

x:=coalesce(new.total_price,0)*r
+coalesce(carry,0);

whole:=floor(x);
carry:=x-whole;

perform public.kinto_credit_points_v310(
new.customer_id::text,
sid,
c,
whole,
carry,
new.id::text
);

insert into public.kinto_loyalty_ledger(
customer_id,
store_id,
order_id,
event_type,
points,
currency,
earn_rate_snapshot,
eligible_product_total,
note
)
values(
new.customer_id::text,
sid,
new.id::text,
'earn',
whole,
c,
r,
new.total_price,
'delivered_store_order'
);

new.loyalty_points_earned:=whole;

end if;

exception when others then

raise warning
'KINTO_V310_EARN_SKIPPED order=% error=%',
new.id,
sqlerrm;

end;
end if;


if coalesce(new.status,'') in(
'ملغي',
'ملغي من قبل العميل',
'رفض الطلب',
'مرفوض'
)
and coalesce(old.status,'') not in(
'ملغي',
'ملغي من قبل العميل',
'رفض الطلب',
'مرفوض'
)
and coalesce(new.loyalty_points_redeemed,0)>0
and sid is not null
and not exists(
select 1
from public.kinto_loyalty_ledger
where order_id=new.id::text
and store_id=sid
and event_type='restore'
)
then
begin

fund:=lower(
trim(
coalesce(
new.reward_discount_snapshot->>'funded_by',
''
)
)
);

if fund not in('vendor','kinto','mixed') then
fund:=null;
end if;

if coalesce(
new.reward_discount_snapshot->>'vendor_points',
''
) ~ '^\s*[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)\s*$'
then
vendor_points:=
(new.reward_discount_snapshot->>'vendor_points')::numeric;
else
vendor_points:=0;
end if;

if coalesce(
new.reward_discount_snapshot->>'kinto_points',
''
) ~ '^\s*[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)\s*$'
then
kinto_points:=
(new.reward_discount_snapshot->>'kinto_points')::numeric;
else
kinto_points:=0;
end if;

update public.kinto_loyalty_coupons
set
status='active',
used_order_id=null,
used_at=null
where used_order_id=new.id::text
and status='used'
and (
campaign_id is not null
or store_id=sid
);

insert into public.kinto_loyalty_ledger(
customer_id,
store_id,
order_id,
event_type,
points,
currency,
note,
funded_by,
funding_snapshot
)
values(
new.customer_id::text,
sid,
new.id::text,
'restore',
new.loyalty_points_redeemed,
coalesce(
new.reward_discount_currency,
c
),
'cancelled_order_original_expiry_restored',
fund,
jsonb_build_object(
'vendor_points',vendor_points,
'kinto_points',kinto_points,
'coupon_ids',
coalesce(
new.reward_discount_snapshot->'coupon_ids',
'[]'::jsonb
),
'restored_original_expiry',true
)
);

new.loyalty_points_redeemed:=0;
new.reward_discount_amount:=0;
new.reward_discount_currency:=null;
new.reward_discount_snapshot:='{}'::jsonb;

exception when others then

raise warning
'KINTO_V310_RESTORE_SKIPPED order=% error=%',
new.id,
sqlerrm;

end;
end if;

return new;
end $function$

CREATE OR REPLACE FUNCTION public.kinto_normalize_currency_v310(v text)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare c text;
begin
c:=upper(trim(coalesce(nullif(v,''),'IQD')));

if c in('$','US$') then
c:='USD';
end if;

if c in('TL','₺') then
c:='TRY';
end if;

return c;
end $function$

CREATE OR REPLACE FUNCTION public.kinto_order_store_id_v310(o orders)
RETURNS text
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
d jsonb;
sid text;
multi_store_text text;
begin
d:=case
when jsonb_typeof(o.details::jsonb)='object'
then o.details::jsonb
else '{}'::jsonb
end;

multi_store_text:=
lower(trim(coalesce(d->>'multi_store','')));

if multi_store_text in('true','t','1','yes','y','on') then
return null;
end if;

sid:=nullif(trim(coalesce(d->>'store_id','')),'');

if sid is not null
and (
coalesce(d->>'source','')<>'local_cart_bundle'
or coalesce(d->>'checkout_contract','')
='independent_vendor_orders'
)
then
return sid;
end if;

return null;

exception when others then
return null;
end
$function$
